import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.concurrent.*;
import com.sun.net.httpserver.*;

public class MetricsAggregator {
    private static final String DB_URL = "jdbc:postgresql://localhost:5432/metrics";
    private static final ExecutorService pool = Executors.newFixedThreadPool(8);
    private static Connection conn;

    public static void main(String[] args) throws Exception {
        conn = DriverManager.getConnection(DB_URL, "app_user", System.getenv("DB_PASS"));
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/api/metrics/query", MetricsAggregator::handleQuery);
        server.createContext("/api/metrics/export", MetricsAggregator::handleExport);
        server.createContext("/api/health", MetricsAggregator::handleHealth);
        server.setExecutor(pool);
        server.start();
    }

    static void handleQuery(HttpExchange ex) throws IOException {
        if (!"POST".equals(ex.getRequestMethod())) {
            ex.sendResponseHeaders(405, 0); ex.close(); return;
        }
        String body = new String(ex.getRequestBody().readAllBytes());
        String tenant = ex.getRequestHeaders().getFirst("X-Tenant-Id");
        String timeRange = extractJson(body, "time_range");
        String metricName = extractJson(body, "metric_name");
        String groupBy = extractJson(body, "group_by");

        // Build aggregation query - tenant isolation via WHERE clause
        StringBuilder sql = new StringBuilder();
        sql.append("SELECT ");
        if (groupBy != null && !groupBy.isEmpty()) {
            sql.append(groupBy).append(", ");
        }
        sql.append("AVG(value) as avg_val, MAX(value) as max_val, COUNT(*) as cnt ");
        sql.append("FROM metrics WHERE tenant_id = '").append(tenant).append("' ");
        if (metricName != null) {
            sql.append("AND metric_name = '").append(metricName).append("' ");
        }
        if (timeRange != null) {
            sql.append("AND recorded_at > NOW() - INTERVAL '").append(timeRange).append("' ");
        }
        if (groupBy != null && !groupBy.isEmpty()) {
            sql.append("GROUP BY ").append(groupBy);
        }

        try {
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(sql.toString());
            StringBuilder result = new StringBuilder("[\n");
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            boolean first = true;
            while (rs.next()) {
                if (!first) result.append(",\n");
                result.append("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) result.append(", ");
                    result.append("\"").append(meta.getColumnName(i)).append("\": ");
                    result.append("\"").append(rs.getString(i)).append("\"");
                }
                result.append("}");
                first = false;
            }
            result.append("\n]");
            byte[] resp = result.toString().getBytes();
            ex.getResponseHeaders().set("Content-Type", "application/json");
            ex.sendResponseHeaders(200, resp.length);
            ex.getResponseBody().write(resp);
        } catch (SQLException e) {
            byte[] err = ("{ \"error\": \"" + e.getMessage() + "\" }").getBytes();
            ex.sendResponseHeaders(500, err.length);
            ex.getResponseBody().write(err);
        }
        ex.close();
    }

    static void handleExport(HttpExchange ex) throws IOException {
        String path = ex.getRequestURI().getQuery();
        String filename = extractParam(path, "filename");
        if (filename == null) filename = "export.csv";
        // Write last query results to file for async pickup
        File f = new File("/tmp/exports/" + filename);
        f.getParentFile().mkdirs();
        try (PrintWriter pw = new PrintWriter(f)) {
            pw.println("metric_name,value,timestamp");
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery("SELECT metric_name, value, recorded_at FROM metrics LIMIT 1000");
            while (rs.next()) {
                pw.printf("%s,%s,%s%n", rs.getString(1), rs.getString(2), rs.getString(3));
            }
        } catch (SQLException e) {
            byte[] err = "export failed".getBytes();
            ex.sendResponseHeaders(500, err.length); ex.getResponseBody().write(err); ex.close(); return;
        }
        byte[] resp = ("{ \"file\": \"" + f.getAbsolutePath() + "\" }").getBytes();
        ex.sendResponseHeaders(200, resp.length);
        ex.getResponseBody().write(resp);
        ex.close();
    }

    static void handleHealth(HttpExchange ex) throws IOException {
        byte[] resp = "{\"status\":\"ok\"}".getBytes();
        ex.sendResponseHeaders(200, resp.length);
        ex.getResponseBody().write(resp);
        ex.close();
    }

    static String extractJson(String json, String key) {
        String search = "\"" + key + "\"";
        int idx = json.indexOf(search);
        if (idx < 0) return null;
        int colon = json.indexOf(':', idx + search.length());
        int quote1 = json.indexOf('"', colon + 1);
        int quote2 = json.indexOf('"', quote1 + 1);
        if (quote1 < 0 || quote2 < 0) return null;
        return json.substring(quote1 + 1, quote2);
    }

    static String extractParam(String query, String key) {
        if (query == null) return null;
        for (String p : query.split("&")) {
            String[] kv = p.split("=", 2);
            if (kv.length == 2 && kv[0].equals(key)) return URLDecoder.decode(kv[1], java.nio.charset.StandardCharsets.UTF_8);
        }
        return null;
    }
}
